// Builds the vendored PenguLoader core.dll (native/vendor/pengu-loader —
// see THIRD_PARTY_NOTICES.md) and copies it to resources/pengu-core/, where
// electron-builder's extraResources config picks it up.
//
// core.vcxproj #includes plugins/dist/preload.g.h, a C header generated by
// building PenguLoader's own `plugins` frontend (a Vite+SolidJS project —
// see plugins/vite.config.ts's custom "pengu-build" plugin, which embeds
// the compiled preload script as a byte array for core.dll to eval at
// runtime). Confirmed against PenguLoader's own
// .github/workflows/build.yml, which builds `plugins` via pnpm before
// building the solution — this script mirrors that order after an earlier
// version skipped it and failed CI with a missing-include error.
//
// Prerequisites this script assumes rather than checks:
//   - the submodule (and its own nested `core/cef` submodule) is checked
//     out: `git submodule update --init --recursive`
//   - `pnpm` and `msbuild` are both on PATH (Visual Studio Build Tools with
//     the C++ workload, plus pnpm, locally; `pnpm/action-setup` and
//     `microsoft/setup-msbuild` in CI)
//
// Not runnable/verified end-to-end in this environment — no MSVC toolchain
// or pnpm available here.
//
// Runs as a predist:win/prebuild:win hook. Locally (no CI env var) it
// degrades gracefully if a prerequisite is missing — logs a warning and
// leaves resources/pengu-core/ empty (still created, so electron-builder's
// extraResources glob doesn't error on a missing path) rather than
// breaking the whole build for contributors without Visual Studio/pnpm. In
// CI (GitHub Actions sets CI=true automatically) both are always set up,
// so a failure there is a real regression, not an expected local-dev gap —
// this rethrows instead.
import { execFile } from 'node:child_process'
import { copyFile, mkdir } from 'node:fs/promises'
import path from 'node:path'
import { promisify } from 'node:util'

const execFileAsync = promisify(execFile)

const root = path.resolve(import.meta.dirname, '..')
const submoduleDir = path.join(root, 'native', 'vendor', 'pengu-loader')
const pluginsDir = path.join(submoduleDir, 'plugins')
const solutionPath = path.join(submoduleDir, 'pengu.sln')
const builtDllPath = path.join(submoduleDir, 'bin', 'core.dll')
const outDir = path.join(root, 'resources', 'pengu-core')

async function main() {
  await mkdir(outDir, { recursive: true })

  try {
    // Generates plugins/dist/preload.g.h, which core.vcxproj needs to
    // compile — must run before the msbuild step below.
    //
    // shell: true because pnpm ships as a .cmd shim on Windows — Node's
    // child_process can't exec that directly (a classic "spawn npm ENOENT
    // on Windows" gotcha, same root cause, different package manager),
    // even when it's genuinely on PATH.
    await execFileAsync('pnpm', ['install', '--frozen-lockfile'], { cwd: pluginsDir, shell: true })
    await execFileAsync('pnpm', ['build'], { cwd: pluginsDir, shell: true })

    await execFileAsync(
      'msbuild',
      [solutionPath, '/t:core:Restore,core:Build', '/p:Configuration=Release', '/p:Platform=x64'],
      { cwd: submoduleDir }
    )
    await copyFile(builtDllPath, path.join(outDir, 'core.dll'))
    console.log(`Built and copied core.dll to ${outDir}`)
  } catch (err) {
    if (process.env.CI) throw err

    console.warn(
      `Skipping Client Theme native build (${err instanceof Error ? err.message : String(err)}). ` +
        'This is fine for local dev — the rest of the app builds normally, just without the client-hook DLL bundled. CI builds it via pnpm/action-setup and microsoft/setup-msbuild.'
    )
  }
}

await main()
